            remark?: null | string;
            isDelete?: boolean;
            /** Format: date-time */
            createTime?: string;
            /** Format: int64 */
            createUserId?: null | number | string;
            /** Format: date-time */
            updateTime?: null | string;
            /** Format: int64 */
            updateUserId?: null | number | string;
            /** Format: int64 */
            id?: number | string;
